const payload = $json.body ?? $json;

const fullName = String(payload.name ?? payload.full_name ?? '').trim();
const email = String(payload.email ?? '').trim().toLowerCase();
const message = String(payload.message ?? payload.description ?? '').trim();

if (!fullName || !email || !message) {
  throw new Error('name, email, and message are required');
}

const text = message.toLowerCase();

const billingWords = ['invoice', 'billing', 'charged', 'charge', 'refund', 'payment', 'receipt', 'subscription'];
const salesWords = ['price', 'pricing', 'quote', 'demo', 'buy', 'purchase', 'plan', 'sales'];
const criticalWords = ['security breach', 'fraud', 'account hacked', 'data loss', 'system down'];
const highWords = ['urgent', 'cannot access', 'locked out', 'charged twice', 'duplicate charge', 'cancel immediately'];

let department = 'CUSTOMER_SUPPORT';
if (billingWords.some((word) => text.includes(word))) department = 'BILLING';
else if (salesWords.some((word) => text.includes(word))) department = 'SALES';

let priority = 'NORMAL';
if (criticalWords.some((word) => text.includes(word))) priority = 'CRITICAL';
else if (highWords.some((word) => text.includes(word))) priority = 'HIGH';

const requiresHumanReview =
  department === 'BILLING' ||
  priority === 'HIGH' ||
  priority === 'CRITICAL';

const now = new Date();
const datePart = now.toISOString().slice(0, 10).replaceAll('-', '');
const randomPart = Math.random().toString(36).slice(2, 8).toUpperCase();
const caseId = `CASE-${datePart}-${randomPart}`;

return [{
  json: {
    success: true,
    caseId,
    customer: {
      name: fullName,
      email
    },
    issue: {
      message,
      department,
      priority,
      status: 'NEW'
    },
    routing: {
      queue: department,
      requiresHumanReview
    },
    receivedAt: now.toISOString()
  }
}];
